"""Skill normalization utilities.Converts raw strings like "Python Programming", "python", "PYTHON" ΓåÆ "Python".Deduplicates equivalent skill names."""# Canonical name map: key is lowercase variant, value is the display name_CANONICAL: dict[str, str] = {    # Languages    "python": "Python",    "python programming": "Python",    "javascript": "JavaScript",    "js": "JavaScript",    "typescript": "TypeScript",    "ts": "TypeScript",    "java": "Java",    "c++": "C++",    "cpp": "C++",    "c#": "C#",    "csharp": "C#",    "go": "Go",    "golang": "Go",    "rust": "Rust",    "r": "R",    "scala": "Scala",    "kotlin": "Kotlin",    "swift": "Swift",    "php": "PHP",    "ruby": "Ruby",    "html": "HTML",    "css": "CSS",    "sql": "SQL",    "bash": "Bash",    "shell": "Shell",    "shell scripting": "Shell",    # Frameworks    "react": "React",    "reactjs": "React",    "react.js": "React",    "vue": "Vue.js",    "vue.js": "Vue.js",    "vuejs": "Vue.js",    "angular": "Angular",    "next": "Next.js",    "nextjs": "Next.js",    "next.js": "Next.js",    "node": "Node.js",    "nodejs": "Node.js",    "node.js": "Node.js",    "express": "Express.js",    "expressjs": "Express.js",    "django": "Django",    "flask": "Flask",    "fastapi": "FastAPI",    "spring": "Spring",    "spring boot": "Spring Boot",    "rails": "Ruby on Rails",    "tensorflow": "TensorFlow",    "pytorch": "PyTorch",    "keras": "Keras",    "sklearn": "scikit-learn",    "scikit-learn": "scikit-learn",    "scikit learn": "scikit-learn",    # Databases    "postgres": "PostgreSQL",    "postgresql": "PostgreSQL",    "mysql": "MySQL",    "mongo": "MongoDB",    "mongodb": "MongoDB",    "redis": "Redis",    "sqlite": "SQLite",    "cassandra": "Cassandra",    "elasticsearch": "Elasticsearch",    "dynamodb": "DynamoDB",    "firebase": "Firebase",    # Tools    "git": "Git",    "github": "GitHub",    "gitlab": "GitLab",    "docker": "Docker",    "kubernetes": "Kubernetes",    "k8s": "Kubernetes",    "jenkins": "Jenkins",    "jira": "Jira",    "confluence": "Confluence",    "terraform": "Terraform",    "ansible": "Ansible",    "webpack": "Webpack",    "vite": "Vite",    "ci/cd": "CI/CD",    "cicd": "CI/CD",    # Cloud    "aws": "AWS",    "amazon web services": "AWS",    "azure": "Azure",    "microsoft azure": "Azure",    "gcp": "GCP",    "google cloud": "GCP",    "google cloud platform": "GCP",    "heroku": "Heroku",    "vercel": "Vercel",    "netlify": "Netlify",    # Soft skills    "leadership": "Leadership",    "communication": "Communication",    "teamwork": "Teamwork",    "agile": "Agile",    "scrum": "Scrum",    "problem solving": "Problem Solving",    "critical thinking": "Critical Thinking",    "collaboration": "Collaboration",    "mentoring": "Mentoring",    "statistics": "Statistics",}def normalize_skill(raw: str) -> str:    """    Return the canonical display name for a skill string.    Examples:        "Python Programming" ΓåÆ "Python"        "python"            ΓåÆ "Python"        "PYTHON"            ΓåÆ "Python"        "AWS"               ΓåÆ "AWS"        "Unknown Skill XYZ" ΓåÆ "Unknown Skill Xyz" (title case fallback)    """    key = raw.strip().lower()    if key in _CANONICAL:        return _CANONICAL[key]    # Title-case fallback for unknown skills    return raw.strip().title()def normalize_skills_list(skills: list[str]) -> list[str]:    """Normalize and deduplicate a list of skill strings."""    seen: set[str] = set()    result: list[str] = []    for raw in skills:        normalized = normalize_skill(raw)        key = normalized.lower()        if key not in seen:            seen.add(key)            result.append(normalized)    return result_CATEGORIES: dict[str, str] = {    "Python": "technical",    "JavaScript": "technical",    "TypeScript": "technical",    "Java": "technical",    "C++": "technical",    "C#": "technical",    "Go": "technical",    "Rust": "technical",    "R": "technical",    "Scala": "technical",    "Kotlin": "technical",    "Swift": "technical",    "PHP": "technical",    "Ruby": "technical",    "HTML": "technical",    "CSS": "technical",    "SQL": "technical",    "Bash": "technical",    "Shell": "technical",    "React": "framework",    "Vue.js": "framework",    "Angular": "framework",    "Next.js": "framework",    "Node.js": "framework",    "Express.js": "framework",    "Django": "framework",    "Flask": "framework",    "FastAPI": "framework",    "Spring": "framework",    "Spring Boot": "framework",    "Ruby on Rails": "framework",    "TensorFlow": "framework",    "PyTorch": "framework",    "Keras": "framework",    "scikit-learn": "framework",    "PostgreSQL": "database",    "MySQL": "database",    "MongoDB": "database",    "Redis": "database",    "SQLite": "database",    "Cassandra": "database",    "Elasticsearch": "database",    "DynamoDB": "database",    "Firebase": "database",    "Git": "tool",    "GitHub": "tool",    "GitLab": "tool",    "Docker": "tool",    "Kubernetes": "tool",    "Jenkins": "tool",    "Jira": "tool",    "Confluence": "tool",    "Terraform": "tool",    "Ansible": "tool",    "Webpack": "tool",    "Vite": "tool",    "CI/CD": "tool",    "AWS": "cloud",    "Azure": "cloud",    "GCP": "cloud",    "Heroku": "cloud",    "Vercel": "cloud",    "Netlify": "cloud",    "Leadership": "soft skill",    "Communication": "soft skill",    "Teamwork": "soft skill",    "Agile": "soft skill",    "Scrum": "soft skill",    "Problem Solving": "soft skill",    "Critical Thinking": "soft skill",    "Collaboration": "soft skill",    "Mentoring": "soft skill",    "Statistics": "soft skill",}def get_skill_category(canonical_skill: str) -> str:    """Return the category for a canonical skill string. Defaults to 'technical'."""    return _CATEGORIES.get(canonical_skill, "technical")